```cpp
#include <iostream>
#include <string>
#include <sstream>

std::string markdownToHtml(const std::string& markdown) {
    // This is a simple implementation and may not handle all markdown
    // features. For a more robust solution, consider using a library like
    // libmarkdown or a custom markdown parser.
    std::string html;
    std::stringstream ss(markdown);
    std::string line;
    while (std::getline(ss, line)) {
        html += line + "\n";
    }
    return html;
}

int main() {
    std::string markdown = "# Hello, World!\nThis is a markdown text.";
    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

